-- Saída web 2025: cobertura cadastral e auditoria 14+, somente fontes congeladas.
-- Não substitui totais, coortes, dados históricos nem consultas do DBA.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=108 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
coleta AS(SELECT result->'rows'->0->'payload' AS dados FROM estudo.notebook_runs WHERE id=117 AND cell_id=312 AND cell_version=3 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
idade AS(SELECT result->'rows'->0->'payload' AS dados FROM estudo.notebook_runs WHERE id=118 AND cell_id=314 AND cell_version=1 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
cobertura AS(SELECT c FROM coleta CROSS JOIN LATERAL jsonb_array_elements(dados->'cobertura')c WHERE (c->>'ano')::int=2025),
mapa AS(SELECT column1 AS serie,column2 AS campo,column3 AS tipo FROM(VALUES('coleta_eventos_cadastrados','cadastradas','numero'),('coleta_eventos_coletados','coletadas','numero'),('coleta_eventos_concluintes','com_concluintes','numero'),('coleta_cobertura_cadastral','coleta_pct','percentual'))t),
base AS(SELECT c FROM cobertura WHERE c->>'escopo'='2025 · ano completo' AND c->>'universo'='Todas as modalidades'),
situacoes AS(SELECT t->>'corte14' AS categoria,sum((t->>'n')::bigint) AS n FROM idade CROSS JOIN LATERAL jsonb_array_elements(dados->'idades')t WHERE t->>'escopo'='2025 · ano completo' AND t->>'universo'='Todas as modalidades' AND t->>'conclusao'='Conclusão registrada' GROUP BY 1),
rotulos AS(SELECT value AS categoria FROM jsonb_array_elements_text('["14+ identificados", "Menos de 14", "Faixa cruza 14", "Sem idade informada", "Dado inválido"]'::jsonb)),
flags AS(SELECT column1 AS categoria,column2 AS campo FROM(VALUES('Conclusão registrada','concluintes'),('Conclusão falsa','conclusao_falsa'),('Conclusão desconhecida','conclusao_desconhecida'))t),
z AS(SELECT column1 AS id FROM(VALUES('qualidade_corte14'),('qualidade_corte14_pct'))t),
novas AS(
 SELECT jsonb_build_object('serie',m.serie,'categoria',c->>'escopo'||' · '||(c->>'universo'),'status','notebook_em_conciliacao','atual',jsonb_build_object('valor',c->m.campo,
 'contagem',CASE WHEN m.tipo='percentual' THEN c->'coletadas' ELSE c->m.campo END,'denominador',c->'cadastradas',
 'fonte','Notebook · #117 · célula 312 rev3 · '||(dados->>'coletado_em'),'nota','"Coleta própria de 01/10/2026, eventos BR pela data final. Todas as modalidades e rua/trail são recortes sobrepostos; não somar. 2025 completo e parcial até 26/09 são sobrepostos; 2026 parcial usa o mesmo dia de corte. Cadastro inclui inativos e não certifica realização; coleta significa ao menos uma linha bruta, não captura completa. Conclusão registrada exige status 0, homologado e concluinte=true. Razão coletadas/cadastradas mede apenas o calendário conhecido do portal, não cobertura nacional e não substitui os 84,1% do PDF. Cada resultado é participação, não pessoa. Outros totais e comparativos mantêm suas próprias coletas e populações."'::jsonb #>> '{}')) AS item FROM cobertura CROSS JOIN mapa m CROSS JOIN coleta
 UNION ALL
 SELECT jsonb_build_object('serie','qualidade_conclusao','categoria',f.categoria,'status','notebook_em_conciliacao','atual',jsonb_build_object('valor',c->f.campo,'contagem',c->f.campo,'denominador',c->'resultados_view',
 'fonte','Notebook · #117 · célula 312 rev3 · '||(dados->>'coletado_em'),'nota','"Coleta própria de 01/10/2026, eventos BR pela data final. Todas as modalidades e rua/trail são recortes sobrepostos; não somar. 2025 completo e parcial até 26/09 são sobrepostos; 2026 parcial usa o mesmo dia de corte. Cadastro inclui inativos e não certifica realização; coleta significa ao menos uma linha bruta, não captura completa. Conclusão registrada exige status 0, homologado e concluinte=true. Razão coletadas/cadastradas mede apenas o calendário conhecido do portal, não cobertura nacional e não substitui os 84,1% do PDF. Cada resultado é participação, não pessoa. Outros totais e comparativos mantêm suas próprias coletas e populações. Idade em 31/12 do ano da prova. Nascimento não posterior à prova e idade 0–120 têm prioridade; plausibilidade não certifica exatidão. Sem nascimento plausível, faixa inteira válida da categoria. Limite inferior >=14 identifica 14+, inclusive faixa ampla que não cabe em grupo de cinco anos. Faixas cruzando 14, faltantes e inválidos permanecem sem decisão; não entram automaticamente nos 14+. Faixas vazias, negativas, sem limite inferior, limite inferior >120 ou superior finito >121 são inválidas. População: participações status 0/homologadas; a distribuição etária aqui usa somente concluinte=true e inclui todas as cinco situações no denominador. Não substitui os totais nem refaz as distribuições etárias anteriores."'::jsonb #>> '{}')) FROM base CROSS JOIN flags f CROSS JOIN coleta
 UNION ALL
 SELECT jsonb_build_object('serie',z.id,'categoria',r.categoria,'status','notebook_em_conciliacao','atual',jsonb_build_object('valor',CASE WHEN z.id='qualidade_corte14' THEN coalesce(s.n,0)::numeric ELSE coalesce(s.n,0)::numeric*100/(b.c->>'concluintes')::numeric END,'contagem',coalesce(s.n,0),'denominador',b.c->'concluintes',
 'fonte','Notebook · #118 · célula 314 rev1 · '||(i.dados->>'coletado_em'),'nota','"Coleta própria de 01/10/2026, eventos BR pela data final. Todas as modalidades e rua/trail são recortes sobrepostos; não somar. 2025 completo e parcial até 26/09 são sobrepostos; 2026 parcial usa o mesmo dia de corte. Cadastro inclui inativos e não certifica realização; coleta significa ao menos uma linha bruta, não captura completa. Conclusão registrada exige status 0, homologado e concluinte=true. Razão coletadas/cadastradas mede apenas o calendário conhecido do portal, não cobertura nacional e não substitui os 84,1% do PDF. Cada resultado é participação, não pessoa. Outros totais e comparativos mantêm suas próprias coletas e populações. Idade em 31/12 do ano da prova. Nascimento não posterior à prova e idade 0–120 têm prioridade; plausibilidade não certifica exatidão. Sem nascimento plausível, faixa inteira válida da categoria. Limite inferior >=14 identifica 14+, inclusive faixa ampla que não cabe em grupo de cinco anos. Faixas cruzando 14, faltantes e inválidos permanecem sem decisão; não entram automaticamente nos 14+. Faixas vazias, negativas, sem limite inferior, limite inferior >120 ou superior finito >121 são inválidas. População: participações status 0/homologadas; a distribuição etária aqui usa somente concluinte=true e inclui todas as cinco situações no denominador. Não substitui os totais nem refaz as distribuições etárias anteriores."'::jsonb #>> '{}')) FROM rotulos r LEFT JOIN situacoes s USING(categoria) CROSS JOIN base b CROSS JOIN idade i CROSS JOIN z
),comparacoes AS(SELECT x AS item FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes')x UNION ALL SELECT item FROM novas),
