SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('contrato_versao',7,'notebook_fontes',payload->'meta'->'notebook_fontes'||(SELECT f FROM fontes)),
 'series',(SELECT jsonb_agg(s ORDER BY s->>'id') FROM series),'comparacoes',(SELECT jsonb_agg(item ORDER BY item->>'serie',item->>'categoria') FROM comparacoes),
 'conciliacao',payload->'conciliacao'||jsonb_build_object('notebook_em_conciliacao',coalesce((payload->'conciliacao'->>'notebook_em_conciliacao')::int,0)+(SELECT count(*) FROM novas))) AS payload FROM anterior
 WHERE (SELECT count(*) FROM cobertura)=4 AND (SELECT count(*) FROM base)=1 AND (SELECT sum(n) FROM situacoes)=(SELECT (c->>'concluintes')::bigint FROM base) AND (SELECT count(*) FROM novas)=29